/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    WorkshopEnhancementDiscounts, LabCostModifiers, EffectiveLevelsIssue, PathExclusion, PathStep, SubstatPair, DamageStatSource, DamageModuleSource (+2 more)
 * depends    —
 * used by    src/mechanics/effective-paths/common/index, src/mechanics/effective-paths/edamage-config, src/mechanics/effective-paths/edamage/types, src/mechanics/effective-paths/eecon/types, src/mechanics/effective-paths/types
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * The shapes more than one Effective Paths module reads: a step a planner takes, an upgrade it
 * leaves out, the lab and workshop discounts it prices with, a problem found in a set of levels,
 * and the per-stat sources the eDamage config is assembled from.
 */

export interface WorkshopEnhancementDiscounts {
  /** Workshop Attack Discount lab level; 0.3% off attack enhancements a level. */
  attackDiscountLabLevel?: number
  /** Workshop Defense Discount lab level. */
  defenseDiscountLabLevel?: number
  /** Workshop Utility Discount lab level. */
  utilityDiscountLabLevel?: number
  /**
   * A flat discount on every enhancement, as a fraction — the sheet reads this
   * from the vault.
   */
  globalDiscountPct?: number
}

export interface LabCostModifiers {
  /**
   * Labs Coin Discount lab level. Each level takes 0.3% off every lab's coin
   * cost.
   */
  coinDiscountLabLevel?: number
  /** Lab Speed lab level. Each level runs labs 2% faster. */
  labSpeedLabLevel?: number
  /** Lab speed from relics, as a fraction — 0.1 for +10%. */
  labSpeedRelicPct?: number
  /**
   * `eEcon!O5` — the "Speed Up" what-if, on top of the two above.
   *
   * The sheet takes it as text (`x1`, `x2`) and `eEcon!E4` strips the `x`
   * before handing the number to `EPP_LAB_DUR_NON_FORMAT`'s `labspeed`
   * argument. It is a planning aid — *how would this path look if labs ran
   * twice as fast* — not anything the player owns, which is why it multiplies
   * the real speed rather than adding to it.
   *
   * Only the economy tab has it: `eHP!O5` and `eDamage!O5` are a different
   * layout entirely. Absent means `1`.
   */
  labSpeedMultiplier?: number
}

/** One thing wrong with a set of levels, and where. */
export interface EffectiveLevelsIssue {
  /** Dotted path — `time.coinsKillBonus`, or `health`. */
  path: string
  message: string
}

/**
 * One upgrade a plan left out, and why, as every planner reports it.
 *
 * `id` matters because `sheetName` is **not unique**. Two eHP upgrades are both
 * called `Assist Module Substats - Armor` — the Assist Module lab and the
 * stone-bought slot upgrade — and on the stone path one is planned while the
 * other is excluded. Compare these lists by `id`; a name-keyed comparison
 * reports that as the same upgrade being planned and left out at once.
 *
 * Optional only because the discount planner predates it and keys its
 * candidates differently; prefer to set it.
 */
export interface PathExclusion {
  id?: string
  sheetName: string
  reason: string
}

export interface PathStep {
  /** 1-based position in the path. */
  step: number
  id: string
  name: string
  /** The level this step buys — the level you end up at, not the one you left. */
  level: number
  /** What this step costs, in the path's currency. */
  cost: number
  /** Every step's cost up to and including this one. */
  cumulativeCost: number
  /** The gain this step buys. */
  gain: number
  /** `gain / cost` — what the step was chosen on. */
  roi: number
  /** The effective value after taking this step. */
  value: number
}

/** A module pair's contribution to one stat. */
export interface SubstatPair {
  /** The primary module's substat, at face value. */
  primary: number
  /** The assist module's substat, before the capacity scaling. */
  assist: number
}

/**
 * One stat's four sources.
 *
 * The sheet keeps a stat's workshop level (`BG`) apart from its resolved value
 * (`BF`), because some stats scale linearly off the level and others read the
 * table. Both are here for the same reason: which one a formula wants is the
 * formula's business, not this type's.
 */
export interface DamageStatSource {
  /** `BG` — the workshop upgrade level. */
  workshopLevel: number
  /**
   * The raw `WSValues` entry for this stat at its level — what
   * `workshopStatValue()` returns.
   *
   * Only Damage / Meter reads it, and it wants the table value untouched:
   * `EPD_DPM` applies its own ÷1000. The sheet's `BH13` shows the divided
   * form, so that cell is *not* this field. Everything else scales off the
   * level rather than the value.
   */
  workshopValue: number
  /** `BI` — the workshop enhancement, the `+` levels. */
  enhancementLevel: number
  /** `BK` — the multiplier those enhancement levels come to. */
  enhancementMultiplier: number
  /** `BL` — the relic bonus, as a fraction. */
  relicPct: number
  /** `BM` — the vault bonus, as a fraction. */
  vaultPct: number
}

/**
 * A module pair, and the two stone ladders that decide how much of the assist
 * module counts.
 *
 * The bonus and substat efficiencies are separate purchases with separate caps
 * — 99 and 69 — so they are separate fields. Treating them as one was the
 * error that took three passes to find.
 */
export interface DamageModuleSource {
  /** `AM` — the primary module's bonus, already resolved. */
  primaryBonus: number
  /** `AN` — whether an assist module is equipped at all. */
  hasAssist: boolean
  /** `AO` — the assist module's bonus at full efficiency. */
  assistBonus: number
  /** `BL41`, `BL43`, `BL45`, `BL47` — the stone-bought bonus efficiency. */
  bonusStoneLevel: number
  /** `BL42`, `BL44`, `BL46`, `BL48` — the stone-bought substat efficiency. */
  substatStoneLevel: number
  /**
   * The primary module's rarity label, e.g. `"Ancestral 5*"`.
   *
   * Given it, `primaryBonus` is ignored and recomputed from the level the path
   * has reached — the coin path buys module levels, so a fixed bonus would
   * make every one of them look worthless.
   */
  primaryRarity?: string
  /** Researched primary-module bonus lab; never applied to the assist. */
  primaryLabLevel?: number
  /** The assist module's rarity label, for the same reason. */
  assistRarity?: string
}

/**
 * A card as the grid reads it.
 *
 * `active` is column `AY` — whether it is in the preset — and `level` is the
 * digit the sheet pulls off `"Lvl 4"` with `RIGHT(...,1)`.
 */
export interface DamageCardSource {
  active: boolean
  level: number
  /** `AV` — the card's own value at that level, where a formula reads it. */
  value: number
}

/**
 * One ultimate weapon's row.
 *
 * The three stats are always damage, then the weapon's quantity-or-equivalent,
 * then its cooldown-or-equivalent — `BI`, `BJ` and `BK`. `plus` is the `BL`
 * column, which reads the string `"Locked"` until the weapon's `+` is bought;
 * `null` here means the same thing.
 */
export interface DamageUltimateWeaponSource {
  /** `BH` — whether it is unlocked and enabled. */
  unlocked: boolean
  /** `BI`. */
  damage: number
  /** `BJ`. */
  quantity: number
  /** `BK`. */
  cooldown: number
  /** `BL`, or `null` for `"Locked"`. */
  plus: number | null
  /**
   * `BM` on the weapon's own row — vault node levels as a fraction (`BN = BM*5%`).
   *
   * Distinct from {@link EffectiveDamageConfig.ultimateWeaponDamageVaultPct}
   * (`BM39`), which is the shared UW Damage vault. Spotlight's
   * `STAT_UW_SL_FINAL_DMG` multiplies both. Optional — absent means zero.
   */
  vaultPct?: number
}
